package com.modelgate.platform;

import org.mybatis.spring.annotation.MapperScan;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Entry point of the ModelGate platform.
 *
 * <p>The class is the component-scan root for every other type of the application and
 * registers the MyBatis mapper interfaces of {@code com.modelgate.platform.mapper}.</p>
 */
@SpringBootApplication
@MapperScan("com.modelgate.platform.mapper")
public class ModelGateApplication {

    public static void main(String[] args) {
        SpringApplication.run(ModelGateApplication.class, args);
    }
}

package com.modelgate.platform.config;

import com.modelgate.platform.entity.User;
import com.modelgate.platform.mapper.UserMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

/**
 * Seeds the platform's initial accounts once, after startup, when the {@code users} table created
 * by the retained SQL initialization is still empty.
 *
 * <p>Passwords are stored verbatim, exactly as the login route compares them.</p>
 */
@Component
public class DataInitializer implements CommandLineRunner {

    private static final Logger log = LoggerFactory.getLogger(DataInitializer.class);

    private static final String[][] SEED_USERS = {
            {"admin", "admin123", "ADMIN"},
            {"alice", "alice123", "USER"},
            {"bob", "bob123", "USER"}
    };

    private final UserMapper userMapper;

    public DataInitializer(UserMapper userMapper) {
        this.userMapper = userMapper;
    }

    @Override
    public void run(String... args) {
        if (userMapper.count() > 0) {
            log.info("Users already present, skipping initialization");
            return;
        }
        for (String[] seed : SEED_USERS) {
            User user = User.of(seed[0], seed[1], seed[2], LocalDateTime.now().withNano(0));
            userMapper.insert(user);
            log.info("Seeded user '{}' with role {}", user.getUsername(), user.getRole());
        }
        log.info("Initialized {} default users", SEED_USERS.length);
    }
}

package com.modelgate.platform.config;

import com.modelgate.platform.security.JwtAuthenticationFilter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpStatus;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

/**
 * Single stateless Spring Security filter chain of the platform.
 *
 * <p>{@code /api/auth/**} is public, every other {@code /api/**} route requires an authenticated
 * caller, and all remaining paths are permitted (the application maps no routes outside
 * {@code /api}). Unauthenticated and denied requests are answered with the JSON envelopes below
 * instead of the framework defaults.</p>
 */
@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private static final String JSON_CONTENT_TYPE = "application/json;charset=UTF-8";
    private static final String UNAUTHORIZED_BODY = "{\"code\":401,\"message\":\"未认证\",\"data\":null}";
    private static final String FORBIDDEN_BODY = "{\"code\":403,\"message\":\"禁止访问\",\"data\":null}";

    private final JwtAuthenticationFilter jwtAuthenticationFilter;

    public SecurityConfig(JwtAuthenticationFilter jwtAuthenticationFilter) {
        this.jwtAuthenticationFilter = jwtAuthenticationFilter;
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .csrf(csrf -> csrf.disable())
                .httpBasic(basic -> basic.disable())
                .formLogin(form -> form.disable())
                .logout(logout -> logout.disable())
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(registry -> registry
                        .antMatchers("/api/auth/**").permitAll()
                        .antMatchers("/api/**").authenticated()
                        .anyRequest().permitAll())
                .exceptionHandling(handling -> handling
                        .authenticationEntryPoint((request, response, authException) ->
                                writeJson(response, HttpStatus.UNAUTHORIZED, UNAUTHORIZED_BODY))
                        .accessDeniedHandler((request, response, accessDeniedException) ->
                                writeJson(response, HttpStatus.FORBIDDEN, FORBIDDEN_BODY)))
                .addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }

    private static void writeJson(HttpServletResponse response, HttpStatus status, String body) throws IOException {
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        response.setStatus(status.value());
        response.setCharacterEncoding(StandardCharsets.UTF_8.name());
        response.setContentType(JSON_CONTENT_TYPE);
        response.setContentLength(bytes.length);
        response.getOutputStream().write(bytes);
        response.getOutputStream().flush();
    }
}

package com.modelgate.platform.controller;

import com.modelgate.platform.dto.ApiResponse;
import com.modelgate.platform.dto.LoginRequest;
import com.modelgate.platform.dto.LoginResponse;
import com.modelgate.platform.service.AuthService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Public credential login route.
 */
@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ResponseEntity<ApiResponse<LoginResponse>> login(@RequestBody(required = false) LoginRequest request) {
        LoginResponse loginResponse = authService.login(request);
        if (loginResponse == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(ApiResponse.<LoginResponse>error(HttpStatus.UNAUTHORIZED.value(), "用户名或密码错误"));
        }
        return ResponseEntity.ok(ApiResponse.success("登录成功", loginResponse));
    }
}

package com.modelgate.platform.controller;

import com.modelgate.platform.dto.ApiResponse;
import com.modelgate.platform.dto.ProviderRegisterRequest;
import com.modelgate.platform.entity.ModelProvider;
import com.modelgate.platform.service.ProviderService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Authenticated provider routes: registration, validation, listing and detail.
 *
 * <p>The owning user of every operation is the authenticated principal name, i.e. the subject of
 * the bearer token. The stored API key is never copied into a response payload.</p>
 */
@RestController
@RequestMapping("/api/providers")
public class ProviderController {

    private static final DateTimeFormatter TIMESTAMP_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE_TIME;
    private static final String NOT_OWNED_MESSAGE = "Provider不存在或无权限";
    private static final String MISSING_FIELDS_MESSAGE = "name、baseUrl、apiKey、modelId不能为空";
    private static final String SUCCESS_MESSAGE = "success";

    private final ProviderService providerService;

    public ProviderController(ProviderService providerService) {
        this.providerService = providerService;
    }

    @PostMapping
    public ResponseEntity<ApiResponse<Map<String, Object>>> register(
            @RequestBody(required = false) ProviderRegisterRequest request, Authentication authentication) {
        if (request == null || isBlank(request.getName()) || isBlank(request.getBaseUrl())
                || isBlank(request.getApiKey()) || isBlank(request.getModelId())) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(ApiResponse.<Map<String, Object>>error(HttpStatus.BAD_REQUEST.value(), MISSING_FIELDS_MESSAGE));
        }
        ModelProvider provider = providerService.register(authentication.getName(), request);

        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", provider.getId());
        data.put("name", provider.getName());
        data.put("baseUrl", provider.getBaseUrl());
        data.put("modelId", provider.getModelId());
        data.put("status", provider.getStatus());
        data.put("createdAt", format(provider.getCreatedAt()));
        return ResponseEntity.ok(ApiResponse.success("注册成功", data));
    }

    @PostMapping("/{id}/validate")
    public ResponseEntity<ApiResponse<Map<String, Object>>> validate(@PathVariable("id") Long id,
            Authentication authentication) {
        ModelProvider provider = providerService.validateProvider(id, authentication.getName());
        if (provider == null) {
            return notFound();
        }

        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", provider.getId());
        data.put("name", provider.getName());
        data.put("status", provider.getStatus());
        data.put("lastValidatedAt", format(provider.getLastValidatedAt()));
        return ResponseEntity.ok(ApiResponse.success("验证完成", data));
    }

    @GetMapping
    public ResponseEntity<ApiResponse<List<Map<String, Object>>>> list(Authentication authentication) {
        List<Map<String, Object>> data = new ArrayList<>();
        for (ModelProvider provider : providerService.listProviders(authentication.getName())) {
            data.add(summary(provider));
        }
        return ResponseEntity.ok(ApiResponse.success(SUCCESS_MESSAGE, data));
    }

    @GetMapping("/{id}")
    public ResponseEntity<ApiResponse<Map<String, Object>>> detail(@PathVariable("id") Long id,
            Authentication authentication) {
        ModelProvider provider = providerService.findOwnedProvider(id, authentication.getName());
        if (provider == null) {
            return notFound();
        }

        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", provider.getId());
        data.put("name", provider.getName());
        data.put("baseUrl", provider.getBaseUrl());
        data.put("modelId", provider.getModelId());
        data.put("status", provider.getStatus());
        data.put("errorMessage", provider.getErrorMessage());
        data.put("lastValidatedAt", format(provider.getLastValidatedAt()));
        data.put("createdAt", format(provider.getCreatedAt()));
        return ResponseEntity.ok(ApiResponse.success(SUCCESS_MESSAGE, data));
    }

    /**
     * The shared projection of a provider: everything but the API key and the validation fields.
     */
    private static Map<String, Object> summary(ModelProvider provider) {
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", provider.getId());
        data.put("name", provider.getName());
        data.put("baseUrl", provider.getBaseUrl());
        data.put("modelId", provider.getModelId());
        data.put("status", provider.getStatus());
        data.put("createdAt", format(provider.getCreatedAt()));
        return data;
    }

    private static ResponseEntity<ApiResponse<Map<String, Object>>> notFound() {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body(ApiResponse.<Map<String, Object>>error(HttpStatus.NOT_FOUND.value(), NOT_OWNED_MESSAGE));
    }

    private static String format(LocalDateTime timestamp) {
        return timestamp == null ? null : timestamp.format(TIMESTAMP_FORMAT);
    }

    private static boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }
}

package com.modelgate.platform.dto;

/**
 * Generic JSON envelope shared by every response body produced by the application.
 *
 * <p>Serializes as {@code {"code":<int>,"message":<string>,"data":<any|null>}}; the
 * {@code data} property is always rendered, even when it is {@code null}.</p>
 *
 * @param <T> the payload type carried by {@code data}
 */
public class ApiResponse<T> {

    private int code;
    private String message;
    private T data;

    public ApiResponse() {
    }

    public ApiResponse(int code, String message, T data) {
        this.code = code;
        this.message = message;
        this.data = data;
    }

    /**
     * Success envelope: {@code code} 200 with the given message and payload.
     */
    public static <T> ApiResponse<T> success(String message, T data) {
        return new ApiResponse<>(200, message, data);
    }

    /**
     * Error envelope: the given code and message with a {@code null} payload.
     */
    public static <T> ApiResponse<T> error(int code, String message) {
        return new ApiResponse<>(code, message, null);
    }

    public int getCode() {
        return code;
    }

    public void setCode(int code) {
        this.code = code;
    }

    public String getMessage() {
        return message;
    }

    public void setMessage(String message) {
        this.message = message;
    }

    public T getData() {
        return data;
    }

    public void setData(T data) {
        this.data = data;
    }

    @Override
    public String toString() {
        return "ApiResponse{code=" + code + ", message='" + message + "', data=" + data + '}';
    }
}

